(function(){AppModule.register({routes:[
{path:"assets/library",title:"数字资产中心",permission:"assets.write",render(){const rows=DB.assets.map(a=>'<tr><td><b>'+a.name+'</b><div class="small muted">'+a.id+'</div></td><td>'+a.type+'</td><td>'+a.project+'</td><td>'+a.version+'</td><td>'+UI.tag(a.status)+'</td><td>'+a.owner+'</td><td><button class="btn" data-action="asset-version">新建版本</button></td></tr>').join("");return UI.head("数字资产中心","统一管理剧本、人物、场景、分镜、视频、音频和成片资产。",UI.btn("导出资产清单","export"))+UI.card("资产目录",'<div class="toolbar"><input class="search" placeholder="搜索资产名称、编号或项目"><span class="pill blue">版本与来源可追溯</span></div>'+UI.table(["资产","类型","项目","版本","状态","创建人","操作"],rows))+'<div class="notice" style="margin-top:14px">资产详情应保留来源、模型调用、生成参数摘要、文件校验、授权、引用关系和版本历史。复用资产不重复计算生成量与成本。</div>';}}
]});})();